{
  "design": {
    "theme": "studio",
    "picture_style": "photo"
  },
  "flow": [
    {"slide": 1, "does": "Recall particles and evidence of a reaction", "look_at": {"kind": "picture", "shows": "Magnesium reacting with acid and producing bubbles"}, "teaches": []},
    {"slide": 2, "does": "Introduce the approved objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Predict the effect of concentration", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 4, "does": "Teach the gas collection investigation", "look_at": {"kind": "diagram", "shows": "An airtight flask connected to a gas syringe"}, "teaches": [2]},
    {"slide": 5, "does": "Teach controls, reliability and safety", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 6, "does": "Model a mean rate calculation", "look_at": {"kind": "diagram", "shows": "Gas volumes at the start and after 40 seconds"}, "teaches": [1]},
    {"slide": 7, "does": "Check a matching mean rate calculation", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 8, "does": "Explain concentration through collision theory", "look_at": {"kind": "diagram", "shows": "More acid particles in the same volume beside equal magnesium surfaces"}, "teaches": [3]},
    {"slide": 9, "does": "Correct the faster-particles misconception", "look_at": {"kind": "diagram", "shows": "Equal particle speeds but different particle numbers at the same temperature"}, "teaches": [3]},
    {"slide": 10, "does": "Check the collision explanation", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 11, "does": "Apply rates, controls and collision theory to new evidence", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 12, "does": "Offer a Higher-tier graph extension before the worksheet exit ticket", "look_at": {"kind": "diagram", "shows": "A gas volume curve with a tangent at 20 seconds"}, "teaches": []}
  ],
  "title": {
    "template": "title",
    "heading": "Rates of reaction",
    "lead": "Recall: what do bubbles show, and how do particles move in a solution?",
    "picture": {
      "shows": "Magnesium ribbon reacting with dilute hydrochloric acid in a flask",
      "must_see": ["magnesium ribbon", "colourless solution", "gas bubbles"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "discussion",
      "heading": "Make a prediction",
      "lead": "Two flasks contain equal masses of magnesium and equal volumes of hydrochloric acid at the same temperature. One acid is twice as concentrated. Predict which produces 20 cm³ of gas first. Explain to a partner.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Measure hydrogen over time",
      "lead": "Magnesium + hydrochloric acid → magnesium chloride + hydrogen",
      "points": [
        "Add magnesium, fit the bung and start timing promptly.",
        "Record gas volume every 10 seconds until it stops rising.",
        "Repeat with different acid concentrations."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "A conical flask containing hydrochloric acid and magnesium, sealed with a bung; a delivery tube connects it to a horizontal clamped gas syringe whose plunger can move freely.",
        "labels": ["Gas syringe", "Clamp stand", "Delivery tube", "Bung", "Conical flask", "Hydrochloric acid", "Magnesium"]
      }
    },
    {
      "template": "explain",
      "heading": "Make the comparison fair and safe",
      "lead": "Change only the hydrochloric acid concentration.",
      "points": [
        {"label": "Control", "text": "Keep magnesium mass and surface area, acid volume and temperature the same."},
        {"label": "Improve", "text": "Use excess acid, check for leaks and repeat each concentration three times."},
        {"label": "Protect", "text": "Wear eye protection. Keep hydrogen away from flames."}
      ]
    },
    {
      "template": "equation-hero",
      "heading": "Worked example: mean rate",
      "lead": "Find the mean rate over the first 40 seconds.",
      "formula": "Mean rate = gas volume ÷ time",
      "points": [
        "Volume produced = 60 − 0 = 60 cm³",
        "Mean rate = 60 ÷ 40 = 1.5 cm³/s"
      ],
      "figure": {
        "kind": "table",
        "shows": "The gas collected at the start and after 40 seconds",
        "alt": "At zero seconds the volume is zero cubic centimetres; at 40 seconds it is 60 cubic centimetres.",
        "title": null,
        "header": ["Time (s)", "Gas (cm³)"],
        "rows": [["0", "0"], ["40", "60"]]
      }
    },
    {
      "template": "practice",
      "heading": "Calculate the mean rate",
      "questions": [
        "A reaction produces 0 cm³ at 0 s and 80 cm³ at 40 s. Calculate its mean rate over these 40 seconds.",
        "A second reaction produces 0 cm³ at 0 s and 60 cm³ at 50 s. Calculate its mean rate over these 50 seconds.",
        "Which reaction has the greater mean rate over its measured interval? Use your answers."
      ],
      "instruction": "Write the calculation and give each rate in cm³/s.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Why does concentration affect rate?",
      "lead": "Higher concentration means more acid particles in the same volume.",
      "points": [
        "Particles collide with the magnesium surface more often.",
        "Successful collisions have enough energy to react.",
        "More successful collisions each second give a faster reaction."
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-sized solution panels at the same temperature, each beside an identical magnesium surface. The higher-concentration panel contains twice as many acid particles. Motion arrows have matching lengths in both panels.",
        "labels": ["Lower concentration", "Higher concentration", "Magnesium surface"]
      }
    },
    {
      "template": "visual-text",
      "heading": "More particles, not faster particles",
      "lead": "Both solutions are at 20 °C. Doubling concentration does not double particle speed.",
      "points": [
        {"label": "Unchanged", "text": "The particles have the same average kinetic energy."},
        {"label": "Changed", "text": "More acid particles reach the magnesium each second."}
      ],
      "figure": {
        "kind": "particles",
        "shows": "Equal-sized panels containing hydrochloric acid particles at 20 degrees Celsius. One has twice as many particles as the other. Matching distributions of motion-arrow lengths show the same average speed; magnesium surfaces have equal sizes.",
        "labels": ["Dilute: 20 °C", "Concentrated: 20 °C", "Equal magnesium surfaces"]
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the best explanation",
      "stem": "Why does more concentrated acid react faster with identical magnesium at the same temperature?",
      "options": [
        "The acid particles move faster.",
        "There are more successful collisions each second.",
        "Every collision now causes a reaction.",
        "Each acid particle has more energy."
      ],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Evaluate a new investigation",
      "questions": [
        "In 30 s, 0.5 mol/dm³ acid gives 24 cm³ of gas and 1.0 mol/dm³ acid gives 42 cm³. Both start at 0 cm³. Calculate both mean rates.",
        "The tests used 0.04 g and 0.08 g of magnesium respectively. Explain why the rates cannot show the effect of concentration alone. State two controls for a repeat.",
        "Stretch: with equal magnesium masses, excess acid and equal temperatures, predict how concentration affects the time to finish and the final gas volume. Explain."
      ],
      "instruction": "Calculate, evaluate and justify.",
      "picture": null
    },
    {
      "template": "big-visual",
      "heading": "Optional Higher: rate at one instant",
      "lead": "Use the tangent’s points (0 s, 12 cm³) and (40 s, 60 cm³) to calculate the rate at 20 s.",
      "figure": {
        "kind": "line-graph",
        "shows": "A gas volume curve with a tangent touching at 20 seconds, for estimating instantaneous rate",
        "alt": "Gas volume rises and levels off. A tangent at 20 seconds passes through zero seconds, 12 cubic centimetres, and 40 seconds, 60 cubic centimetres.",
        "title": null,
        "x": {"label": "Time (s)", "min": 0, "max": 80, "step": 10},
        "y": {"label": "Gas volume (cm³)", "min": 0, "max": 80, "step": 10},
        "y2": null,
        "qualitative": false,
        "series": [
          {
            "label": "Gas collected",
            "points": [[0, 0], [10, 22], [20, 36], [30, 46], [40, 53], [50, 58], [60, 61], [70, 63], [80, 64]],
            "style": "line",
            "axis": "left"
          },
          {
            "label": "Tangent at 20 s",
            "points": [[0, 12], [20, 36], [40, 60]],
            "style": "tangent",
            "axis": "left"
          }
        ],
        "segments": null,
        "annotations": null,
        "intervals": null
      }
    }
  ]
}
